local function r8(a) return emu:read8(a) end
local function r16(a) return emu:read16(a) end
local function r32(a) return emu:read32(a) end

local function levelFromExp(growth, exp)
  local lv = 1
  for l = 2, MAX_LEVEL do
    if r32(EXP_TABLES + (growth * (MAX_LEVEL + 1) + l) * 4) <= exp then lv = l else break end
  end
  return lv
end

-- one BoxPokemon at `addr` as a Showdown set, or nil for an empty slot / egg / bad egg
local function readMon(addr, partyLevel)
  local flags = r8(addr + 21)
  if (flags & 2) == 0 or (flags & 1) == 1 then return nil end
  local s = addr + SECURE
  local species = r16(s) & 0x7FF
  local ivw = r32(s + 40)
  if species == 0 or ((ivw >> 30) & 1) == 1 or (flags & 4) == 4 then return nil end
  local info = SPECIES_INFO + species * INFO_SIZE
  local abilityNum = (r8(s + 19) >> 4) & 3
  local ability = r16(info + INFO_ABIL + abilityNum * 2)
  if ability == 0 then ability = r16(info + INFO_ABIL) end
  local nature = ((r32(addr) % 25) ~ ((r8(addr + 20) >> 3) & 31)) % 25
  local level = partyLevel or levelFromExp(r8(info + INFO_GROWTH), r32(s + 4) & 0xFFFFFF)
  local item = r16(s + 2) & 0x3FF
  local name = SPECIES[species] or ("Species #" .. species)
  local lines = { name .. ((item ~= 0 and ITEMS[item]) and (" @ " .. ITEMS[item]) or "") }
  lines[#lines + 1] = "Ability: " .. (ABILITIES[ability] or ("Ability #" .. ability))
  lines[#lines + 1] = "Level: " .. level
  lines[#lines + 1] = NATURES[nature + 1] .. " Nature"
  lines[#lines + 1] = string.format("IVs: %d HP / %d Atk / %d Def / %d SpA / %d SpD / %d Spe",
    ivw & 31, (ivw >> 5) & 31, (ivw >> 10) & 31, (ivw >> 20) & 31, (ivw >> 25) & 31, (ivw >> 15) & 31)
  for i = 0, 3 do
    local m = r16(s + 12 + i * 2) & 0x7FF
    if m ~= 0 then lines[#lines + 1] = "- " .. (MOVES[m] or ("Move #" .. m)) end
  end
  return table.concat(lines, "\n")
end

local function export()
  local out = {"=== Party ==="}
  local count = r8(PARTY_COUNT)
  if count > 6 then count = 6 end
  for i = 0, count - 1 do
    local base = PARTY + i * MON_SIZE
    local set = readMon(base, r8(base + LEVEL))
    if set then out[#out + 1] = set .. "\n" end
  end
  local storage = r32(STORAGE_PTR)
  if storage >= 0x02000000 and storage < 0x02040000 then
    for box = 0, N_LEGACY do
      local sets = {}
      for slot = 0, IN_BOX - 1 do
        local addr = box < N_LEGACY and (storage + LEGACY + (box * IN_BOX + slot) * BOX_SIZE)
                                     or (storage + EXTRA + slot * BOX_SIZE)
        local set = readMon(addr, nil)
        if set then sets[#sets + 1] = set .. "\n" end
      end
      if #sets > 0 then
        out[#out + 1] = "=== Box " .. (box + 1) .. " ==="
        for _, v in ipairs(sets) do out[#out + 1] = v end
      end
    end
  end
  return table.concat(out, "\n")
end

local buffer = console:createBuffer("SoulGold sets")
local dir = (script and script.dir) and (script.dir .. "/") or ""
local last = nil
local frames = 0

local function refresh(force)
  local ok, text = pcall(export)
  if not ok then console:error("SoulGold export failed: " .. tostring(text)) return end
  if force or text ~= last then
    last = text
    buffer:clear()
    buffer:print(text .. "\n")
    local f = io.open(dir .. "soulgold_sets.txt", "w")
    if f then f:write(text) f:close() end
  end
end

callbacks:add("frame", function()
  frames = frames + 1
  if frames % 120 == 0 then refresh(false) end
end)
refresh(true)
console:log("SoulGold export loaded: sets are in the 'SoulGold sets' tab and " .. dir .. "soulgold_sets.txt")
